@startuml

class EBike {
  + frame : Frame
  + wheels : Wheel[]
  + driveSystem : DriveSystem
  + controller : Controller
  + battery : Battery?
  + connectBattery(battery : Battery)
  + disconnectBattery()
}

class Frame {
  - material : string
  + getMaterial()
}

class Wheel {}

class DriveSystem {
  + motor : Motor
}

class Motor {}

class Battery {
  + energy : int
  + getEnergy()
}

abstract class Controller {
  + state : string
  + turnOn()
  + turnOff()
  + chargeBattery()
  + commandDriveSystem()
}

class BasicController extends Controller {}

class AdvancedController extends Controller {
  + estimateNextInspectionDate()
}

EBike "1" -- "*" Wheel
EBike "1" -- "1 DriveSystem"
EBike "1" -- "1 Controller"
EBike "0..1" -- "1 Battery"
BasicController --|> Controller
AdvancedController --|> Controller

@enduml

